INSERT INTO public.ruleset_chunks (id, ruleset_id, ruleset_version_id, chunk_index, content, embedding, metadata, created_at, embedding_model) VALUES ('b055cffe-ab5f-4346-b104-8abf1df99b5c', '20000000-0000-0000-0000-000000000002', '20000000-0000-0000-0001-000000000002', 1, 'Every DMCC employer must provide comprehensive medical insurance coverage for all employees from the first day of employment. The medical insurance plan must meet or exceed the minimum coverage requirements set by the Dubai Health Authority (DHA), including in-patient and out-patient coverage with a minimum annual limit of AED 150,000. The employer must provide proof of insurance to DMCC within thirty (30) days of the employee start date.', '[-0.007426897,0.004863242,0.061043594,0.07217844,-0.031996172,0.054265864,0.027903128,0.031380016,0.005847994,0.02141147,0.028805358,-0.052769482,0.04262489,-0.031424027,0.007916522,0.015657,-0.034724873,-0.016823297,0.024822341,-0.0017590744,0.0043901214,0.05739066,-0.01311535,0.0009675597,0.005886504,0.020289183,-0.013324404,-0.06130766,0.02403014,-0.023347965,0.029069426,-0.005083299,-0.0027534533,0.008989297,0.0015679005,0.017384442,0.011519942,0.06826144,0.024558274,0.0018539736,-0.05056892,0.020872332,0.019012857,-0.0524614,-0.049424626,-0.010997309,-0.0007392513,0.012312145,0.06645697,-0.019188901,-0.0036474317,0.013478443,0.042844944,-0.0020011363,-0.015844047,0.025086408,0.034020692,0.009071818,-0.00047105784,0.005069545,0.03252431,-0.02403014,-0.03111595,0.015271901,-0.0023628536,-0.034856904,0.052681457,0.037277523,0.011217366,0.022456737,0.022478743,0.02376607,0.035473064,-0.03558309,-0.017670514,-0.056862526,-0.007382886,-0.04986474,-0.008345632,0.009247863,-0.028981404,-0.00955044,-0.023854094,0.028585302,-0.007300365,-0.037783653,-0.036463317,0.014545715,-0.03608922,-0.019684028,0.027529033,-0.024492256,-0.0022555762,0.015822042,0.043747175,-0.022841835,0.02653878,0.03659535,-0.05659846,0.04748813,-0.006051546,-0.056026313,-0.04200873,0.0279031