INSERT INTO public.ruleset_chunks (id, ruleset_id, ruleset_version_id, chunk_index, content, embedding, metadata, created_at, embedding_model) VALUES ('bfe6fb3a-2774-4716-a2c3-1448595ded21', '20000000-0000-0000-0000-000000000004', '20000000-0000-0000-0001-000000000004', 0, 'Commercial contracts must specify clear payment terms including: (a) the total contract value or method of calculation, (b) currency of payment (AED is standard for UAE-domiciled contracts), (c) payment schedule and due dates, (d) acceptable methods of payment, and (e) late payment penalties. Under UAE Commercial Transactions Law, late payment interest may be charged at the rate agreed upon, provided it does not exceed twelve percent (12%) per annum. If no rate is specified, the court may apply the prevailing commercial interest rate.', '[-0.05703313,-0.01470964,0.066615805,0.028956348,-0.021549448,0.030738633,-0.03386342,-0.010792084,0.06439374,0.0316645,0.014721213,-0.05527399,0.011787387,-0.059070025,0.0015479263,0.045089502,-0.0020065175,-0.010884671,-0.010045608,-0.03150247,0.029164668,0.031780228,-0.049765106,0.024928847,0.005699841,-0.027289797,-0.0070886347,-0.052866746,0.043584976,-0.015427183,0.048052263,-0.012464424,-0.010583765,-0.014686493,-0.014524467,0.039974112,-0.0071059945,0.016202593,0.009773635,-0.06981003,-0.049579933,-0.0020065175,0.015010545,-0.024072424,-0.010097687,0.0088361995,-0.00023273144,0.016711818,-0.012047785,0.013181967,-0.000655337,0.009304917,0.01555449,-0.00222641,0.021734621,-0.01467492,0.0018285784,0.041848984,0.06587511,-0.012915782,-0.039395448,-0.017730266,-0.049024418,-0.059162613,-0.027104624,0.011121923,-0.019477831,0.06828236,-0.0336551,0.027081477,0.011162429,0.006521544,0.06707874,-0.02853971,0.016063714,-0.0340023,-0.012036212,-0.015542916,0.068652704,0.0024231556,-0.02165361,-0.068513826,-0.049579933,0.07027296,-0.0133208465,-0.011341815,-0.07448564,0.01939682,-0.0018835515,-0.009247052,-0.04529782,0.024951994,-0.0014423202,-0.015577636,0.02511402