INSERT INTO public.ruleset_chunks (id, ruleset_id, ruleset_version_id, chunk_index, content, embedding, metadata, created_at, embedding_model) VALUES ('dd210a51-92c3-442a-af41-4980e7a34515', '20000000-0000-0000-0000-000000000004', '20000000-0000-0000-0001-000000000004', 4, 'Commercial contracts should include a force majeure clause defining events beyond the reasonable control of the parties. Under UAE Civil Code (Art. 273), if a contractual obligation becomes impossible due to a cause beyond the debtor control, the obligation is extinguished. The force majeure clause should specify: (a) qualifying events (natural disasters, war, epidemics, government actions), (b) notification requirements, (c) mitigation obligations, (d) consequences (suspension or termination), and (e) the time period after which either party may terminate.', '[-0.049789447,0.033994522,0.0445751,0.05290287,-0.006619187,0.047941644,-0.07355777,-0.023958165,0.02716018,0.043031044,0.030931726,-0.043486666,-0.01750351,-0.03786732,-0.029590169,0.06500219,0.026881745,0.009827531,-0.030400166,0.013504154,0.02337598,0.039765745,-0.0310836,0.021211773,-0.018553972,0.0034013507,-0.0062743057,-0.009568078,0.048447892,0.018781785,0.060445957,-0.0045973607,-0.016820075,-0.0052523185,-0.0155418,0.044094164,0.013529466,-0.0086062085,-0.0011453851,-0.028653612,0.0019680373,-0.06976091,0.016060704,0.011757599,-0.008739099,0.040196057,-0.001873116,0.013390248,0.0064546564,-0.0109602595,0.014997584,-0.03191891,0.061154705,-0.034551397,0.03202016,-0.039715122,-0.012105645,0.031792346,0.019136157,-0.03769013,-0.0521435,-0.041993234,-0.014871022,-0.043891665,-0.020528339,0.004426502,0.028197989,0.028577674,-0.016402422,0.0439676,0.012130957,0.013972432,0.05811722,0.0006830387,0.006821686,-0.01527602,0.023287388,0.008201211,0.038601376,-0.005030835,-0.011396898,-0.00973261,-0.053814117,0.07856962,-0.02672987,0.027286744,-0.109349474,0.019288031,-0.008327772,-0.014871022,-0.024236603,0.0007633264,-0.020528339,0.01187150