INSERT INTO public.ruleset_chunks (id, ruleset_id, ruleset_version_id, chunk_index, content, embedding, metadata, created_at, embedding_model) VALUES ('af60d8e6-f0b2-4f0b-bf16-87103dc12446', '20000000-0000-0000-0000-000000000005', '20000000-0000-0000-0001-000000000005', 2, 'DIFC employers must enroll all eligible employees in the DIFC Employee Workplace Savings Scheme (DEWS) or an approved Qualifying Scheme. Contribution rates: (a) employees with less than five (5) years of service – 5.83% of basic salary per month (equivalent to 21 days per year), (b) employees with five (5) or more years of service – 8.33% of basic salary per month (equivalent to 30 days per year). Contributions must be made monthly. This replaces the traditional gratuity liability model. Employers who fail to enroll employees face penalties from the DIFC Authority.', '[-0.025664108,0.037148148,0.08378424,0.025028987,0.024873447,0.060868006,0.023680972,0.04414745,0.0057452605,0.014374493,0.019507315,-0.017122367,0.032481946,-0.025962226,0.060712468,0.032793026,-0.0035385361,-0.001753066,-0.0016453221,0.028515676,0.020129476,0.04990243,-0.0012435103,0.06460097,0.023253238,0.03255972,-0.049280275,-0.034426197,0.0025971949,-0.011406271,0.018768499,0.002846707,-0.021814492,-0.020894213,0.029811842,0.028204596,0.013596793,0.06931902,0.0046629612,-0.03725184,-0.02791944,0.023175467,0.03452989,-0.068126544,-0.039507173,-0.045936164,-0.004896271,-0.008807455,0.048217416,0.0131885,0.0013512542,0.020647941,0.0057517416,-0.005686933,0.022916235,0.02552153,0.030745083,-0.0033829962,-0.01512627,-0.0108878035,0.028437907,-0.00012850281,-0.01637059,0.016189126,0.019986896,-0.026675118,-0.026597349,0.109914966,-0.028567523,0.012300625,0.01512627,0.058586754,0.081969604,-0.032170866,0.008528779,0.00783533,0.022877349,-0.03258564,-0.008606549,0.008463971,-0.0129422285,-0.0031707487,-0.048995115,0.0056901737,-0.01458188,-0.03504836,-0.05832752,0.024264248,-0.0022780136,0.014309685,0.021931147,-0.035566825,-0.0585867