c_emp_04", "isPartial": false, "rulesetKey": "difc_employment_law_v1", "tokenCount": 103, "clauseOrder": 4, "clauseTitle": "DIFC Notice Period for Termination", "authorityName": "Dubai International Financial Centre", "isRequired": true, "severity": "critical", "article": "Art. 59-62", "section": null, "source": null, "rulesetName": "DIFC Employment Law No. 2 of 2019"}'::jsonb, '2026-03-04T19:09:54.002Z'::timestamptz, 'text-embedding-3-small');
