INSERT INTO public.ruleset_chunks (id, ruleset_id, ruleset_version_id, chunk_index, content, embedding, metadata, created_at, embedding_model) VALUES ('75b5ba5e-cd99-4b3e-9355-088b257664d5', '20000000-0000-0000-0000-000000000005', '20000000-0000-0000-0001-000000000005', 5, 'DIFC employers must not discriminate against employees or applicants on the grounds of: (a) sex, gender, or gender identity, (b) marital status, (c) race, nationality, or ethnic origin, (d) religion or belief, (e) disability, (f) age, or (g) pregnancy or maternity. This applies to recruitment, terms of employment, promotion, training, and termination. Employers must have a written equal opportunity and anti-discrimination policy accessible to all employees. Harassment including sexual harassment is prohibited and must be addressed through a formal complaints procedure.', '[0.021726377,0.019874563,0.09440713,0.0779885,0.010385492,0.040975805,0.012502693,0.0006225545,-0.008628038,0.00454697,0.0071241762,-0.01717351,0.020971498,0.008026493,-0.013576037,0.0362814,0.024415636,0.0047976137,0.015628366,0.028709015,0.05331337,0.05175643,-0.015368876,0.05236977,0.0013461036,0.016807865,0.013116033,-0.01622991,0.013587832,0.011936533,0.0638345,-0.0072834087,-0.019166864,9.062794e-05,0.051237453,0.03444138,0.002596373,-0.0057205716,0.030431082,-0.019426353,-0.008191623,0.00084407924,-0.0019800845,-0.05005795,-0.06638222,0.031115193,0.03892348,-0.021148423,0.030407494,-0.0059918566,-0.010226259,0.014590407,0.013434498,0.011040114,-0.00022539495,0.029393123,-0.012632438,-0.010768829,0.008946503,-0.021195604,0.030761342,0.016383246,-0.012325768,-0.010137796,-0.029794153,-0.013139622,0.023342293,0.07317614,0.030171594,0.022776132,0.058927786,0.025736677,0.042414796,0.013635012,0.0047710747,-0.062136024,0.032247514,-0.030784933,-0.043240447,-0.00086619484,-0.03545575,0.016819661,-0.021938687,0.03930092,0.0078082858,0.022092022,-0.07473308,0.007336486,-0.016465811,-0.005316593,0.006994431,-0.016218117,-0.07369511