INSERT INTO public.ruleset_chunks (id, ruleset_id, ruleset_version_id, chunk_index, content, embedding, metadata, created_at, embedding_model) VALUES ('0556ae0a-6357-4a78-bd84-8b6e02675ce3', '20000000-0000-0000-0000-000000000005', '20000000-0000-0000-0001-000000000005', 7, 'DIFC employers must comply with DIFC Data Protection Law No. 5 of 2020 in respect of employee personal data. The employer must: (a) have a lawful basis for processing employee data, (b) provide a privacy notice to employees, (c) limit data collection to what is necessary, (d) maintain appropriate security measures, (e) not transfer data outside DIFC without adequate safeguards, and (f) appoint a Data Protection Officer if processing on a large scale. Employee monitoring (email, CCTV, internet) requires prior notice and must be proportionate.', '[0.01067198,0.039734226,0.0893141,0.038468357,0.040085856,0.048196796,0.013139253,0.0024877845,0.011527614,0.032279663,0.05532317,-0.010361373,-0.0019412924,-0.022691876,-0.008269173,-0.0026255064,0.022398852,0.007108793,0.007524889,0.008151963,0.048759405,0.07107621,0.0030240207,0.030779375,0.015026336,-0.003026951,-0.004999011,-0.0033141158,0.011345938,-0.020593816,0.022305083,-0.011920268,-0.026512926,0.008099218,0.03225622,0.02447347,0.019116968,0.021730755,0.015178708,0.004237145,0.0039470503,0.021297077,-0.00023203938,-0.030990353,-0.018413708,-0.04278169,-0.008321918,-0.020160139,0.008972433,0.0020145488,0.011416265,0.045289986,0.0030005786,0.017311933,-0.0077534486,0.046227667,0.006704418,0.008544616,0.009347506,0.025153289,0.016667277,-0.0005032709,-0.008192986,0.009798765,0.0020687585,-0.018706733,-0.0041199354,0.065121934,0.015213871,0.015917132,0.0749207,0.0528852,0.038304262,-0.0090369,0.011574498,-0.027896006,0.031506076,-0.019292783,-0.024520354,0.0055352473,-0.02782568,0.014428564,-0.024309376,0.00093328545,-0.004697195,0.006891954,-0.06591897,0.014545774,-0.003305325,-0.0051543145,0.031459194,-0.0025185521,-0.05115049,0.027708469,0.0346707